CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY, employee_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department_id TEXT NOT NULL REFERENCES departments(id), role TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, employee_id TEXT UNIQUE REFERENCES employees(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kpi_templates (id TEXT PRIMARY KEY, department_id TEXT NOT NULL REFERENCES departments(id), name TEXT NOT NULL, target NUMERIC NOT NULL, weight NUMERIC NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS kpi_assignments (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), template_id TEXT NOT NULL REFERENCES kpi_templates(id), cycle TEXT NOT NULL, UNIQUE(employee_id, template_id, cycle));
CREATE TABLE IF NOT EXISTS attendance_records (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), work_date DATE NOT NULL, status TEXT NOT NULL, UNIQUE(employee_id, work_date));
CREATE TABLE IF NOT EXISTS performance_reviews (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), reviewer_id TEXT NOT NULL REFERENCES users(id), review_type TEXT NOT NULL, score NUMERIC NOT NULL, comment TEXT NOT NULL, evidence TEXT, status TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS monthly_performance (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), cycle TEXT NOT NULL, overall_score NUMERIC NOT NULL, eligible BOOLEAN NOT NULL, finalized BOOLEAN NOT NULL DEFAULT FALSE, components JSONB NOT NULL, generated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(employee_id, cycle));
CREATE TABLE IF NOT EXISTS awards (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), award_type TEXT NOT NULL, cycle TEXT NOT NULL, score NUMERIC NOT NULL, status TEXT NOT NULL, approved_by TEXT REFERENCES users(id), override_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bonuses (id TEXT PRIMARY KEY, award_id TEXT NOT NULL UNIQUE REFERENCES awards(id), amount NUMERIC NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS certificates (id TEXT PRIMARY KEY, award_id TEXT NOT NULL UNIQUE REFERENCES awards(id), certificate_number TEXT NOT NULL UNIQUE, issued_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, action TEXT NOT NULL, actor_user_id TEXT NOT NULL REFERENCES users(id), target_type TEXT NOT NULL, target_id TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_monthly_performance_cycle ON monthly_performance(cycle);
CREATE INDEX IF NOT EXISTS idx_audit_events_target ON audit_events(target_type, target_id);
